namespace Opencart\Catalog\Controller\Extension\Linnworks; class Channel extends \Opencart\System\Engine\Controller{private array $b=[];public function addNewUser():void{$this->run(false,fn()=>$this->model_extension_linnworks_channel->add($this->b));}public function configTest():void{$this->run(true,fn()=>['Error'=>null]);}public function userConfig():void{$this->run(true,fn($a)=>['Error'=>null,'StepName'=>'UserConfig','AccountName'=>$a['account_name'],'WizardStepDescription'=>'GB Appliances OpenCart','WizardStepTitle'=>'GB Appliances OpenCart','ConfigItems'=>[]]);}public function saveConfig():void{$this->run(true,fn()=>['Error'=>null]);}public function configDeleted():void{$this->run(true,fn()=>['Error'=>null]);}public function orders():void{$this->run(true,fn()=>['Error'=>null,'HasMorePages'=>false,'Orders'=>[]]);}public function products():void{$this->run(true,fn()=>['Error'=>null,'HasMorePages'=>false,'Products'=>[]]);}public function inventoryUpdate():void{$this->run(true,fn()=>['Error'=>null,'Products'=>$this->results($this->b['Products']??[],'Dry-run: not applied')]);}public function priceUpdate():void{$this->run(true,fn()=>['Error'=>null,'Products'=>$this->results($this->b['Products']??[],'Dry-run: not applied')]);}public function despatch():void{$this->run(true,fn()=>['Error'=>'Dry-run: not applied']);}public function cancel():void{$this->run(true,fn()=>['Error'=>'Cancellation disabled in test build']);}public function refund():void{$this->run(true,fn()=>['Error'=>'Refund unsupported']);}public function shippingTags():void{$this->run(true,fn()=>['Error'=>null,'ShippingTags'=>[]]);}public function paymentTags():void{$this->run(true,fn()=>['Error'=>null,'PaymentTags'=>[]]);}private function run(bool $auth,callable $f):void{$this->response->addHeader('Content-Type: application/json');try{if(($this->request->server['REQUEST_METHOD']??'')!=='POST')throw new \RuntimeException('POST required');$this->b=json_decode(file_get_contents('php://input')?:'{}',true);$this->load->model('extension/linnworks/channel');$a=[];if($auth){$a=$this->model_extension_linnworks_channel->auth($this->b);if(!$a)throw new \RuntimeException('Invalid AuthorizationToken');}$o=$f($a);}catch(\Throwable $e){$o=['Error'=>$e->getMessage()];}$this->response->setOutput(json_encode($o));}private function results(array $p,string $e):array{$o=[];foreach($p as $x)$o[]=['SKU'=>$x['SKU']??'','Error'=>$e];return $o;}}
